import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final primeiro=TextEditingController(),segundo=TextEditingController();String resultado='';double? ler(TextEditingController x)=>double.tryParse(x.text.replaceAll(',','.'));void somar()=>operar((a,b)=>a+b);void subtrair()=>operar((a,b)=>a-b);void multiplicar()=>operar((a,b)=>a*b);void dividir(){final b=ler(segundo);if(b==0){setState(()=>resultado='Erro: não é possível dividir por zero.');return;}operar((a,b)=>a/b);}void operar(double Function(double,double) f){final a=ler(primeiro),b=ler(segundo);setState(()=>resultado=a==null||b==null?'Informe dois números.':'Resultado: ${f(a,b)}');}void limpar(){primeiro.clear();segundo.clear();setState(()=>resultado='');}@override void dispose(){primeiro.dispose();segundo.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Quatro operações')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:primeiro,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Primeiro número')),TextField(controller:segundo,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Segundo número')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:somar,child:const Text('+')),const SizedBox(width:5),ElevatedButton(onPressed:subtrair,child:const Text('-')),const SizedBox(width:5),ElevatedButton(onPressed:multiplicar,child:const Text('×')),const SizedBox(width:5),ElevatedButton(onPressed:dividir,child:const Text('÷'))]),const SizedBox(height:10),ElevatedButton(onPressed:limpar,child:const Text('Limpar')),const SizedBox(height:24),Text(resultado)])));}
